  "created_at": string;
  "started_at": string;
  "completed_at": string;
  "name": string;
  "steps"?: Array<{
    "status": "queued" | "in_progress" | "completed";
    "conclusion": string;
    "name": string;
    "number": number;
    "started_at"?: string;
    "completed_at"?: string;
  }>;
  "check_run_url": string;
